export const CHARACTER_SETS = {
  MINIMAL: { name: 'Minimal', chars: ' .:-=+*#%@' },
  STANDARD: { name: 'Standard', chars: ' .\'^"`,:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$' },
  BLOCKS: { name: 'Blocks', chars: ' ░▒▓█' }
} as const;

export const EMOJI_COLOR_PALETTE = [
  { emoji: '⬛', rgb: [0, 0, 0] },
  { emoji: '🖤', rgb: [30, 30, 30] },
  { emoji: '🤎', rgb: [139, 69, 19] },
  { emoji: '🟫', rgb: [165, 42, 42] },
  // ... 23 total entries matching PRD appendix
] as const;

export function rgbToNearestEmoji(r: number, g: number, b: number): string {
  let minDist = Infinity;
  let nearest = EMOJI_COLOR_PALETTE[0].emoji;
  for (const { emoji, rgb: [er, eg, eb] } of EMOJI_COLOR_PALETTE) {
    const dist = (r - er) ** 2 + (g - eg) ** 2 + (b - eb) ** 2; // squared Euclidean
    if (dist < minDist) { minDist = dist; nearest = emoji; }
  }
  return nearest;
}
