startWebcam: async () => {
  const { videoRef } = get();
  if (!videoRef) { set({ webcamError: 'Video element not ready' }); return; }

  try {
    const stream = await navigator.mediaDevices.getUserMedia({ 
      video: { facingMode: 'user', width: 640, height: 480 } 
    });
    videoRef.srcObject = stream;
    await videoRef.play();
    set({ streamRef: stream, isWebcamActive: true, webcamError: null });
  } catch (err) {
    set({ webcamError: err instanceof Error ? err.message : 'Camera access denied', isWebcamActive: false });
  }
},

stopWebcam: () => {
  const { streamRef, videoRef, animationFrameId, segmenter } = get();

  if (animationFrameId) cancelAnimationFrame(animationFrameId);
  if (streamRef) streamRef.getTracks().forEach(track => track.stop());
  if (videoRef) videoRef.srcObject = null;
  if (segmenter) segmenter.close();

  set({ 
    streamRef: null, 
    isWebcamActive: false, 
    animationFrameId: null, 
    segmenter: null,
    asciiOutput: '',
    previousMaskData: null
  });
},
