startRenderLoop: () => {
  const { animationFrameId, videoRef } = get();
  if (animationFrameId || !videoRef) return;

  let lastFrameTime = 0;
  let isFirstFrame = true;
  const targetFrameTime = 33; // ~30fps

  const loop = (timestamp: number) => {
    if (timestamp - lastFrameTime < targetFrameTime) {
      const id = requestAnimationFrame(loop);
      set({ animationFrameId: id });
      return;
    }

    const frameStart = performance.now();

    // Portrait detection (first frame only)
    if (isFirstFrame && videoRef.videoHeight > videoRef.videoWidth) {
      set({ asciiWidth: 80 });
      isFirstFrame = false;
    }

    // Call ASCII conversion based on colorMode
    const { colorMode } = get();
    if (colorMode === 'monochrome') get().updateAsciiOutput();
    else if (colorMode === 'color') get().updateColorAsciiOutput();
    else if (colorMode === 'emoji') get().updateEmojiOutput();

    lastFrameTime = timestamp;
    const id = requestAnimationFrame(loop);
    set({ animationFrameId: id });
  };

  const id = requestAnimationFrame(loop);
  set({ animationFrameId: id });
},

stopRenderLoop: () => {
  const { animationFrameId } = get();
  if (animationFrameId) cancelAnimationFrame(animationFrameId);
  set({ animationFrameId: null });
},
