```ts
// Per-cell average RGB with Gray World white balance
function computeCellBrightness(imageData: ImageData, x: number, y: number, cellWidth: number, cellHeight: number): number {
  const { data, width } = imageData;
  let rSum = 0, gSum = 0, bSum = 0, count = 0;

  for (let dy = 0; dy < cellHeight; dy++) {
    for (let dx = 0; dx < cellWidth; dx++) {
      const px = (x * cellWidth + dx) + (y * cellHeight + dy) * width;
      const i = px * 4;
      rSum += data[i]; gSum += data[i+1]; bSum += data[i+2]; count++;
    }
  }

  // Gray World white balance
  const avgR = rSum / count, avgG = gSum / count, avgB = bSum / count;
  const grayAvg = (avgR + avgG + avgB) / 3;
  const r = avgR * (grayAvg / (avgR + 0.001));
  const g = avgG * (grayAvg / (avgG + 0.001));
  const b = avgB * (grayAvg / (avgB + 0.001));

  // RGB to LAB L* (simplified D65 illuminant)
  const X = 0.4124 * r + 0.3576 * g + 0.1805 * b;
  const Y = 0.2126 * r + 0.7152 * g + 0.0722 * b;
  const Z = 0.0193 * r + 0.1192 * g + 0.9505 * b;

  const Yn = 100; // D65 white point
  const fy = Y / Yn > 0.008856 ? Math.pow(Y / Yn, 1/3) : (903.3 * Y / Yn + 16) / 116;
  const L = 116 * fy - 16; // L* in [0, 100]

  return L;
}
