After computing per-cell LAB L* brightness, apply unsharp mask:

```ts
function applyUnsharpMask(brightnessGrid: number[][], k: number = 0.5): number[][] {
  const rows = brightnessGrid.length;
  const cols = brightnessGrid[0].length;
  const sharpened: number[][] = [];

  for (let y = 0; y < rows; y++) {
    sharpened[y] = [];
    for (let x = 0; x < cols; x++) {
      if (y === 0 || y === rows - 1 || x === 0 || x === cols - 1) {
        sharpened[y][x] = brightnessGrid[y][x]; // edge cells unchanged
        continue;
      }

      // 3×3 average (blurred)
      let sum = 0;
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          sum += brightnessGrid[y + dy][x + dx];
        }
      }
      const blurred = sum / 9;

      // Unsharp mask formula: original + k * (original - blurred)
      const original = brightnessGrid[y][x];
      sharpened[y][x] = original + k * (original - blurred);
    }
  }

  return sharpened;
}
```

