  const currentMask = maskCtx.getImageData(0, 0, vw, vh).data;

  if (previousMaskData) {
    // Temporal smoothing: 0.7 * current + 0.3 * previous, gamma 0.8
    for (let i = 0; i < currentMask.length; i += 4) {
      const curr = currentMask[i] / 255;
      const prev = previousMaskData[i] / 255;
      const blended = 0.7 * curr + 0.3 * prev;
      const gamma = Math.pow(blended, 0.8);
      currentMask[i] = currentMask[i+1] = currentMask[i+2] = gamma * 255;
    }
  }

  maskData = new Uint8ClampedArray(currentMask);
}
