updateEmojiOutput: () => {
  const { canvasRef, videoRef, asciiWidth } = get();
  if (!canvasRef || !videoRef) return;

  const ctx = canvasRef.getContext('2d')!;
  const vw = videoRef.videoWidth, vh = videoRef.videoHeight;
  canvasRef.width = vw; canvasRef.height = vh;
  ctx.drawImage(videoRef, 0, 0);

  const imageData = ctx.getImageData(0, 0, vw, vh);

  // Square cells (1:1 aspect ratio)
  const cellSize = Math.floor(vw / asciiWidth);
  const rows = Math.floor(vh / cellSize);

  // Gray World white balance per frame
  const { data } = imageData;
  let rSum = 0, gSum = 0, bSum = 0;
  for (let i = 0; i < data.length; i += 4) {
    rSum += data[i]; gSum += data[i+1]; bSum += data[i+2];
  }
  const grayAvg = (rSum + gSum + bSum) / (data.length / 4 * 3);
  const rScale = grayAvg / (rSum / (data.length / 4));
  const gScale = grayAvg / (gSum / (data.length / 4));
  const bScale = grayAvg / (bSum / (data.length / 4));

  const rowsOutput: string[] = [];

  for (let y = 0; y < rows; y++) {
    let rowStr = '';
    for (let x = 0; x < asciiWidth; x++) {
      // Compute per-cell average RGB
      let r = 0, g = 0, b = 0, count = 0;
      for (let dy = 0; dy < cellSize; dy++) {
        for (let dx = 0; dx < cellSize; dx++) {
          const px = (x * cellSize + dx) + (y * cellSize + dy) * vw;
          const i = px * 4;
          r += data[i] * rScale; g += data[i+1] * gScale; b += data[i+2] * bScale; count++;
        }
      }
      r /= count; g /= count; b /= count;

      rowStr += rgbToNearestEmoji(r, g, b);
    }
    rowsOutput.push(rowStr);
  }

  set({ emojiOutput: { cols: asciiWidth, rows: rowsOutput } });
},
