takeScreenshot: () => {
  const { colorMode, asciiOutput, coloredAsciiOutput, emojiOutput, asciiColor, selectedCharset } = get();

  const canvas = document.createElement('canvas');
  const scale = 3;
  const fontSize = 12 * scale;
  const lineHeight = 6 * scale; // 2:1 aspect ratio for ASCII

  if (colorMode === 'monochrome') {
    const lines = asciiOutput.split('\n');
    const width = lines[0].length * fontSize * 0.6; // monospace char width ~0.6em
    const height = lines.length * lineHeight;
    canvas.width = width; canvas.height = height;

    const ctx = canvas.getContext('2d')!;
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = asciiColor;
    ctx.font = `${fontSize}px monospace`;

    lines.forEach((line, i) => {
      ctx.fillText(line, 0, (i + 1) * lineHeight);
    });
  } else if (colorMode === 'color') {
    // Parse coloredAsciiOutput HTML and render each <span> with its color
    const lines = coloredAsciiOutput.split('\n');
    const width = lines[0].replace(/<[^>]*>/g, '').length * fontSize * 0.6;
    const height = lines.length * lineHeight;
    canvas.width = width; canvas.height = height;

    const ctx = canvas.getContext('2d')!;
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, width, height);
    ctx.font = `${fontSize}px monospace`;

    lines.forEach((line, y) => {
      const regex = /<span style="color:(#[0-9a-f]{6})">(.)<\/span>/g;
      let match, x = 0;
      while ((match = regex.exec(line)) !== null) {
        ctx.fillStyle = match[1];
        ctx.fillText(match[2], x * fontSize * 0.6, (y + 1) * lineHeight);
        x++;
      }
    });
  } else if (colorMode === 'emoji') {
    const EMOJI_SIZE = 24 * scale;
    canvas.width = emojiOutput.cols * EMOJI_SIZE;
    canvas.height = emojiOutput.rows.length * EMOJI_SIZE;

    const ctx = canvas.getContext('2d')!;
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.font = `${EMOJI_SIZE * 0.9}px serif`;

    emojiOutput.rows.forEach((row, y) => {
      [...row].forEach((emoji, x) => {
        ctx.fillText(emoji, x * EMOJI_SIZE, (y + 1) * EMOJI_SIZE);
      });
    });
  }

  canvas.toBlob((blob) => {
    if (!blob) return;

    // Web Share API or download link
    if (navigator.share && navigator.canShare({ files: [new File([blob], 'ascii.png', { type: 'image/png' })] })) {
      navigator.share({ files: [new File([blob], 'ascii.png', { type: 'image/png' })] });
    } else {
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'ascii.png';
      a.click();
      URL.revokeObjectURL(url);
    }
  });
},
