```glsl
#version 300 es
precision highp float;

in vec2 vTexCoord;
out vec4 fragColor;
uniform sampler2D uTexture;

vec3 rgb2lab(vec3 rgb) {
  // RGB to XYZ (D65)
  float x = 0.4124 * rgb.r + 0.3576 * rgb.g + 0.1805 * rgb.b;
  float y = 0.2126 * rgb.r + 0.7152 * rgb.g + 0.0722 * rgb.b;
  float z = 0.0193 * rgb.r + 0.1192 * rgb.g + 0.9505 * rgb.b;

  // XYZ to LAB
  float fy = (y / 100.0 > 0.008856) ? pow(y / 100.0, 1.0/3.0) : (903.3 * y / 100.0 + 16.0) / 116.0;
  float L = 116.0 * fy - 16.0;

  return vec3(L, 0.0, 0.0);
}

void main() {
  vec4 color = texture(uTexture, vTexCoord);
  vec3 lab = rgb2lab(color.rgb);
  fragColor = vec4(lab.x / 100.0, lab.x / 100.0, lab.x / 100.0, 1.0); // L* normalized to [0,1]
}
