```ts
const sobelX = [[-1, 0, 1], [-2, 0, 2], [-1, 0, 1]];
const sobelY = [[-1, -2, -1], [0, 0, 0], [1, 2, 1]];

function computeEdgeDirection(brightnessGrid: number[][], x: number, y: number): number {
  let gx = 0, gy = 0;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      const b = brightnessGrid[y + dy]?.[x + dx] ?? 0;
      gx += b * sobelX[dy + 1][dx + 1];
      gy += b * sobelY[dy + 1][dx + 1];
    }
  }
  return Math.atan2(gy, gx); // angle in radians
}
